"use client";

import * as React from "react";
import { motion } from "motion/react";

export function FlipCardTailwind() {
  const [flipped, setFlipped] = React.useState(false);
  const face = "absolute inset-0 flex flex-col items-center justify-center gap-2 rounded-2xl p-6 text-center [backface-visibility:hidden]";
  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={flipped}
      onPointerEnter={() => setFlipped(true)}
      onPointerLeave={() => setFlipped(false)}
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setFlipped((f) => !f); } }}
      className="h-56 w-72 cursor-pointer rounded-2xl [perspective:1000px] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      <motion.div className="relative h-full w-full [transform-style:preserve-3d]" animate={{ rotateY: flipped ? 180 : 0 }} transition={{ type: "spring", stiffness: 120, damping: 16 }}>
        <div className={face + " border border-zinc-800 bg-zinc-900 text-zinc-100"} aria-hidden={flipped}>
          <h3 className="text-xl font-semibold">Flip Card</h3>
          <p className="text-sm text-zinc-400">Hover or press Enter to turn me over.</p>
        </div>
        <div className={face + " bg-sky-400 text-zinc-950 [transform:rotateY(180deg)]"} aria-hidden={!flipped}>
          <h3 className="text-xl font-semibold">Spring-driven 3D</h3>
          <p className="text-sm opacity-80">Perspective and backface culling.</p>
        </div>
      </motion.div>
    </div>
  );
}
